<section class="card shadow-sm" id="companion-mobile-root">
  <div class="card-header"><strong><i class="fa-solid fa-mobile-screen-button me-2" aria-hidden="true"></i>Prüf-Companion</strong></div>
  <div class="card-body">
    <p class="mb-1"><strong><?= htmlspecialchars((string) $device->external_number) ?> · <?= htmlspecialchars((string) $device->name) ?></strong></p>
    <p class="small text-body-secondary">Prüfung <?= htmlspecialchars((string) $inspection->external_number) ?> · Übertragungen erscheinen direkt am verbundenen Prüfplatz.</p>
    <section class="border rounded-3 p-3 mb-3"><h2 class="h6"><i class="fa-solid fa-barcode me-2" aria-hidden="true"></i>Barcode scannen</h2><div id="companion-scan-result" class="mb-2"></div><div class="d-grid gap-2"><input type="hidden" id="inspection-companion-camera-code"><?= \Ceneos\PhpBase\View\BarcodeScanner::render('inspection-companion-camera-code') ?><form hx-post="<?= htmlspecialchars(url_for('companion/' . $session['token'] . '/barcode-foto'), ENT_QUOTES) ?>" hx-target="#companion-scan-result" hx-swap="innerHTML" hx-encoding="multipart/form-data" class="input-group"><input class="form-control" name="barcode_photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" required><button class="btn btn-secondary" type="submit"><i class="fa-solid fa-image me-1" aria-hidden="true"></i>Foto auswerten</button></form><form hx-post="<?= htmlspecialchars(url_for('companion/' . $session['token'] . '/barcode'), ENT_QUOTES) ?>" hx-target="#companion-scan-result" hx-swap="innerHTML" class="input-group"><input class="form-control" name="barcode" placeholder="Barcode manuell eingeben" autocomplete="off"><button class="btn btn-secondary" type="submit">Senden</button></form></div><video id="companion-camera" class="w-100 rounded mt-3 d-none" playsinline></video></section>
    <section class="border rounded-3 p-3"><h2 class="h6"><i class="fa-solid fa-camera me-2" aria-hidden="true"></i>Foto aufnehmen</h2><div id="companion-photo-result" class="mb-2" aria-live="polite"></div><form method="post" enctype="multipart/form-data" hx-post="<?= htmlspecialchars(url_for('companion/' . $session['token'] . '/fotos'), ENT_QUOTES) ?>" hx-target="#companion-photo-result" hx-swap="innerHTML" hx-encoding="multipart/form-data" hx-indicator="#companion-photo-uploading" hx-disabled-elt="find button[type=submit]" class="vstack gap-2"><input class="form-control" name="photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" required><select class="form-select" name="media_type"><option value="type_plate">Typenschild</option><option value="condition">Zustand</option><option value="defect">Mangel</option><option value="disposal">Aussonderung</option><option value="other">Sonstiges</option></select><input class="form-control" name="caption" maxlength="1000" placeholder="Bemerkung (optional)"><button class="btn btn-primary" type="submit"><span id="companion-photo-uploading" class="spinner-border spinner-border-sm htmx-indicator me-1" aria-hidden="true"></span><i class="fa-solid fa-upload me-1" aria-hidden="true"></i>Foto an Prüfplatz senden</button></form></section>
  </div>
</section>
<script>
(()=>{const input=document.getElementById('inspection-companion-camera-code');if(!input||input.dataset.linked)return;input.dataset.linked='1';input.addEventListener('change',()=>{if(input.value)htmx.ajax('POST', <?= json_encode(url_for('companion/' . $session['token'] . '/barcode'), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>, {target:'#companion-scan-result',swap:'innerHTML',values:{barcode:input.value}});});})();
</script>
